                let url =
                  'https://developer.mozilla.org/docs/Web/JavaScript/Reference/Errors/Illegal_character#What_went_wrong';
                p5._friendlyError(
                  translator('fes.globalErrors.syntax.invalidToken', {
                    url
                  })
                );
